Lemma asan_mem_facts_justified_w1 :
  forallb (mjustify (s_know (a_ss HS_asan2_1)) (var_ranges (s_know (a_ss HS_asan2_1))) 65536 6287360) (asan_mem_facts ++ asan_mem_facts_w1) = true.
